SELECT p.id AS position_id, s.id, s.decision, s.latest_price, s.total_score, s.confidence_score, s.generated_at FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal e ON e.id=p.signal_id JOIN crypto_ai.trade_signal s ON s.symbol=e.symbol AND s.interval_code='1m' AND s.generated_at BETWEEN e.generated_at - INTERVAL 30 MINUTE AND e.generated_at WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at LIMIT 400;
SELECT p.id AS position_id, MIN(s.latest_price) AS ref_low_30m, MAX(s.latest_price) AS high_30m, SUM(s.decision IN ('BUY','STRONG_BUY')) AS buys, SUM(s.decision='WATCH') AS watches FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal e ON e.id=p.signal_id JOIN crypto_ai.trade_signal s ON s.symbol=e.symbol AND s.interval_code='1m' AND s.generated_at BETWEEN e.generated_at - INTERVAL 30 MINUTE AND e.generated_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id ORDER BY p.id;